SELECT users.user_id AS userId , users.nickname AS nickName , users.bio AS bio , profile.path AS profilePath FROM follow follow JOIN users users
ON users.user_id = follow.follower_id
ON users.user_id = follow.following_id
LEFT JOIN profile_files profile ON profile.user_id = users.user_id AND profile.file_type = 0 WHERE
follow.following_id = #{userId}
follow.follower_id = #{userId}
